style.css:
@-moz-document domain("roblox.com") {
body, html {
        background: url("https://static.vecteezy.com/system/resources/previews/032/944/569/large_2x/night-sky-with-planets-and-galaxies-scene-free-photo.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
        color: #ffffff !important;
    }

    /* Make everything else transparent so you can see the image */
    .container-main,
    .content,
    .section,
    .game-home-page,
    .theme-container,
    .app,
    .rbx-body,
    #responsive-app-container,
    .content {
        background-color: rgba(0, 0, 0, 0.4) !important;
    }

    /* Optional: Darker header */
    .header, .navigation {
        background-color: rgba(0, 0, 0, 0.6) !important;
    }

    /* Optional: style buttons */
    button, .btn-primary, .btn-control-md {
        background-color: rgba(30, 30, 30, 0.8) !important;
        color: white !important;
        border: 1px solid #444 !important;
    }
}
